//! `live_day` is the only place that resolves rt trip ids and an alert's
//! informed entities, so no consumer joins rt by hand (tests/rt_join_law_test,
//! tests/alert_test). The types in [`gtfs_rt`] are generated by `build.rs`.

pub mod gtfs_rt {
    include!(concat!(env!("OUT_DIR"), "/transit_realtime.rs"));
}

pub mod overview;
pub mod progress;
pub mod live;
pub mod encode;
pub mod load;

pub use overview::{
    AlertView, InformedView,
    decode_overview, RtOverview, StopUpdateView, TripUpdateView, VehicleView,
};
pub use progress::{late_trips, resolve_instance, trip_progress, LateTrip, ProgressStop, StopName, TripProgress};
pub use live::live_day;
pub use encode::{encode_alerts, entity_reading, read_alerts, DroppedAlert, EncodedAlerts, EntityNames, EntityReading, EntityRoute, EntityStop, EntityTrip, ReadAlerts, SkippedEntity};

use prost::Message;

#[derive(Debug, thiserror::Error)]
pub enum RtError {
    #[error("protobuf decode failed: {0}")]
    Decode(#[from] prost::DecodeError),
}

pub type Result<T> = std::result::Result<T, RtError>;

pub fn decode(bytes: &[u8]) -> Result<gtfs_rt::FeedMessage> {
    Ok(gtfs_rt::FeedMessage::decode(bytes)?)
}
